-- Seed: 2026 emerging + prospective partners (from Top Donors & Partners workbook).
-- Idempotent via (external_source, external_id). Emerging→outreach, Prospective→prospect.
on conflict (external_source, external_id) where external_id is not null do update set
  kind = excluded.kind, status = excluded.status, city = coalesce(excluded.city, partners.city),
  region = coalesce(excluded.region, partners.region), domain = coalesce(excluded.domain, partners.domain);

-- Contacts (linked by partner external_id).

-- Mark the first-imported contact per org as primary (idempotent).
update partner_contacts c set is_primary = true
from (
  select distinct on (partner_id) id from partner_contacts
  where external_source = 'partner_import_2026'
  order by partner_id, created_at
) f
where c.id = f.id and c.is_primary = false;
